def remove_extras(lst):

    def position(i):
        n = len(lst)
        for j in range(n):
            if lst[j] == i:
                return j
    def helper(start,i):
        idxs = [j for j in range(start, len(lst)) if lst[j] == i]
        for j in reversed(idxs):
            del lst[j]

    for i in lst:
        index = position(i)
        helper(index+1,i)
    return lst

